// "Ação" -> "ACAO": tira acento e passa para maiuscula (UTF-8)
static std::string maiuscula(const std::string &s) {
    static const std::unordered_map<std::string, char> AC = {
        {"á", 'A'}, {"à", 'A'}, {"â", 'A'}, {"ã", 'A'}, {"ä", 'A'}, {"Á", 'A'}, {"À", 'A'}, {"Â", 'A'}, {"Ã", 'A'},
        {"é", 'E'}, {"ê", 'E'}, {"è", 'E'}, {"É", 'E'}, {"Ê", 'E'}, {"í", 'I'}, {"Í", 'I'}, {"ó", 'O'}, {"ô", 'O'},
        {"õ", 'O'}, {"ö", 'O'}, {"Ó", 'O'}, {"Ô", 'O'}, {"Õ", 'O'}, {"ú", 'U'}, {"ü", 'U'}, {"Ú", 'U'}, {"ç", 'C'},
        {"Ç", 'C'}, {"ñ", 'N'}};
    std::string o;
    for (size_t i = 0; i < s.size();) {
        unsigned char c = s[i];
        int n = c < 0x80 ? 1 : (c >> 5) == 6 ? 2 : (c >> 4) == 14 ? 3 : 4;
        std::string ch = s.substr(i, n);
        i += n;
        if (n == 1) o += char(toupper(c));
        else if (AC.count(ch)) o += AC.at(ch);
        else o += '?';
    }
    return o;
}

// largura em pixels de tela do texto com blocos de tamanho b
static float largura(const std::string &up, float b) { return up.empty() ? 0 : (up.size() * 6 - 1) * b; }

